	// boundary, so APP_DB_PASSWORD matches via the leading `_` but mydbpassword
	// does not.
	credentialValuePattern = regexp.MustCompile(`(?i)(?:^|[^A-Za-z0-9])(` + dbPasswordKeyShape + `)\s*=\s*("[^"]*"|'[^']*'|[^\s,;&]+)`)

