	keywordUserPattern      = regexp.MustCompile(`(?i)(?:^|\s)user=`)
	semicolonServerPattern  = regexp.MustCompile(`(?i)(?:^|;)\s*(?:server|data source|datasource|addr|address|network address)\s*=`)
