   147	func detectPII(cfg *PIIConfig, s string) []taggedRegion {
   148		if cfg == nil || !cfg.Enabled {
   149			return nil
   150		}
   151	
   152		patterns := cfg.patterns
   153		if patterns == nil {
   154			patterns = compilePIIPatterns(cfg)
   155		}
   156		var regions []taggedRegion
   157		for _, p := range patterns {
   158			for _, loc := range p.regex.FindAllStringIndex(s, -1) {
   159				// Skip allowlisted email addresses (noreply, bot accounts, etc.).
   160				if p.label == labelEmail && isAllowlistedEmail(s[loc[0]:loc[1]]) {
   161					continue
   162				}
   163				regions = append(regions, taggedRegion{
   164					region: region{loc[0], loc[1]},
   165					label:  p.label,
   166				})
   167			}
   168		}
   169		return regions
   170	}
