   172	// compilePIIPatterns builds the pattern list from config.
   173	// Builtin regexes are pre-compiled package vars; only custom patterns
   174	// need compilation here.
   175	func compilePIIPatterns(cfg *PIIConfig) []piiPattern {
   176		var patterns []piiPattern
   177		for _, bp := range builtinPIIPatterns {
   178			if enabled, ok := cfg.Categories[bp.category]; ok && enabled {
   179				patterns = append(patterns, piiPattern{regex: bp.regex, label: bp.label})
   180			}
   181		}
   182		for label, pattern := range cfg.CustomPatterns {
   183			compiled, err := regexp.Compile(pattern)
   184			if err != nil {
   185				slog.Warn("skipping invalid custom PII pattern", slog.String("label", label), slog.String("error", err.Error()))
   186				continue
   187			}
   188			patterns = append(patterns, piiPattern{regex: compiled, label: strings.ToUpper(label)})
   189		}
   190		return patterns
   191	}
