   193	// replacementToken returns the redaction placeholder for a given label.
   194	// Empty label (secrets) returns "REDACTED" for backward compatibility.
   195	// Non-empty label (PII) returns "[REDACTED_<LABEL>]".
   196	func replacementToken(label string) string {
   197		if label == "" {
   198			return "REDACTED"
   199		}
   200		return "[REDACTED_" + label + "]"
   201	}
