     9	// CustomRulesConfig configures inline custom_redactions and parsed rule packs.
    10	type CustomRulesConfig struct {
    11		// Inline maps a label (used only in logs/diagnostics) to a Go RE2 regex
    12		// string. Failed compilations are logged via slog.Warn and dropped.
    13		Inline map[string]string
    14	
    15		// Packs are pre-parsed rule packs (see LoadPacks). Per-rule regex
    16		// compilation failures are logged and dropped; sample mismatches are
    17		// logged but do not drop the rule.
    18		Packs []*Pack
    19	}
    20	
    21	// compiledCustomRule is a compiled regex retained across calls.
    22	// label is unused for replacement (custom rules always emit the bare REDACTED
    23	// token to match other secret layers), but is preserved for diagnostics.
    24	type compiledCustomRule struct {
    25		label string
    26		regex *regexp.Regexp
    27	}
    28	
    29	type customRulesState struct {
    30		rules []compiledCustomRule
    31	}
    32	
    33	var (
    34		customConfig   *customRulesState
    35		customConfigMu sync.RWMutex
    36	)
    37	
    38	// componentAttr tags every warning emitted by this package so log aggregators
    39	// can filter redaction failures with the same key the CLI uses elsewhere
    40	// (`logging.WithComponent(ctx, "redaction")`).
    41	var componentAttr = slog.String("component", "redaction")
    42	
    43	// ConfigureCustomRules compiles user-defined redaction rules and stores the
    44	// result for use by redact.String(). Sample-validation runs here too, so
    45	// failures surface the next time any process initializes redaction.
    46	//
    47	// Call once at process startup after loading settings. Thread-safe.
    48	func ConfigureCustomRules(cfg CustomRulesConfig) {
    49		state := &customRulesState{}
    50	
    51		for label, pattern := range cfg.Inline {
    52			compiled, ok := compileCustomRule(
    53				label,
    54				pattern,
    55				"skipping invalid custom_redactions pattern",
    56				slog.String("label", label),
    57			)
    58			if ok {
    59				state.rules = append(state.rules, compiled)
    60			}
    61		}
    62	
    63		for _, pack := range cfg.Packs {
    64			for _, rule := range pack.Rules {
    65				compiled, ok := compileCustomRule(
    66					pack.Name+"."+rule.ID,
    67					rule.Regex,
    68					"skipping invalid pack rule",
    69					slog.String("pack", pack.sourcePath),
    70					slog.String("rule", rule.ID),
    71				)
    72				if ok {
    73					state.rules = append(state.rules, compiled)
    74					runRuleSamples(pack, rule, compiled.regex)
    75				}
    76			}
    77		}
    78	
    79		customConfigMu.Lock()
    80		defer customConfigMu.Unlock()
    81		customConfig = state
    82	}
    83	
    84	func compileCustomRule(label, pattern, warning string, attrs ...any) (compiledCustomRule, bool) {
    85		compiled, err := regexp.Compile(pattern)
    86		if err != nil {
    87			all := make([]any, 0, len(attrs)+2)
    88			all = append(all, componentAttr)
    89			all = append(all, attrs...)
    90			all = append(all, slog.String("error", err.Error()))
    91			slog.Warn(warning, all...)
    92			return compiledCustomRule{}, false
    93		}
    94		return compiledCustomRule{label: label, regex: compiled}, true
    95	}
    96	
    97	// runRuleSamples checks each sample against the compiled regex and logs a
    98	// warning per mismatch. Failures never drop the rule — sample validation
    99	// is informational, not gating.
   100	func runRuleSamples(pack *Pack, rule Rule, compiled *regexp.Regexp) {
   101		for i, s := range rule.Samples {
   102			got := compiled.MatchString(s.Input)
   103			if got != s.Redacted {
   104				slog.Warn("redactor pack sample mismatch",
   105					componentAttr,
   106					slog.String("pack", pack.sourcePath),
   107					slog.String("rule", rule.ID),
   108					slog.Int("sample_index", i),
   109					slog.Int("sample_length", len(s.Input)),
   110					slog.Bool("expected", s.Redacted),
   111					slog.Bool("got", got))
   112			}
   113		}
   114	}
   115	
   116	// getCustomRulesConfig returns the currently-configured custom rules.
   117	// Returns nil if ConfigureCustomRules has never been called.
   118	func getCustomRulesConfig() *customRulesState {
   119		customConfigMu.RLock()
   120		defer customConfigMu.RUnlock()
   121		return customConfig
   122	}
   123	
   124	// detectCustomRules returns tagged regions for every match of every
   125	// configured custom rule. Returns nil if no rules are configured.
   126	//
   127	// All regions use an empty label so they are replaced with the bare
   128	// "REDACTED" token used by the built-in secret layers, not the
   129	// "[REDACTED_<LABEL>]" token used by PII.
   130	func detectCustomRules(cfg *customRulesState, s string) []taggedRegion {
   131		if cfg == nil || len(cfg.rules) == 0 || s == "" {
   132			return nil
   133		}
   134		var regions []taggedRegion
   135		for _, rule := range cfg.rules {
   136			for _, loc := range rule.regex.FindAllStringIndex(s, -1) {
   137				regions = append(regions, taggedRegion{region: region{loc[0], loc[1]}})
   138			}
   139		}
   140		return regions
   141	}
