    19	// RedactorsDirName is the .entire subdirectory used for user-defined rule packs.
    20	const RedactorsDirName = "redactors"
    21	
    22	// maxIdentifierLen caps the length of pack Name and rule ID values. Both fields
    23	// flow into slog attrs and into directory-derived diagnostics; the bound prevents
    24	// a runaway YAML scalar from blowing up log lines.
    25	const maxIdentifierLen = 64
    26	
    27	// maxPackFileBytes caps the per-file size LoadPacks will parse. The trust
    28	// boundary is "user owns repo," so this is not a security barrier — it is a
    29	// runaway-input guard that keeps an accidentally large YAML out of the
    30	// redaction startup path.
    31	const maxPackFileBytes = 1 << 20 // 1 MiB
    32	
    33	// maxPackFiles caps how many pack files LoadPacks will accept under one
    34	// .entire/redactors/ tree. Same trust model as maxPackFileBytes: prevents a
    35	// runaway directory from stalling every CLI invocation.
    36	const maxPackFiles = 256
    37	
    38	// identifierPattern restricts pack Name and rule ID to a conservative set of
    39	// characters that play well with filesystems, log greps, and JSON. Disallowing
    40	// whitespace and control characters avoids log-line injection from a malformed
    41	// pack scalar.
    42	var identifierPattern = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
    43	
    44	// Pack is a versioned bundle of redaction rules loaded from a single file
    45	// under .entire/redactors/. Both YAML and JSON encodings are accepted; the
    46	// schema is identical.
    47	type Pack struct {
    48		Name        string `json:"name"                  yaml:"name"`
    49		Version     string `json:"version"               yaml:"version"`
    50		Description string `json:"description,omitempty" yaml:"description"`
    51		Rules       []Rule `json:"rules"                 yaml:"rules"`
    52	
    53		// sourcePath is the file the pack was loaded from. Populated by
    54		// ParsePack; used in log lines so users can find the offending file.
    55		sourcePath string
    56	}
    57	
    58	// Rule is a single redaction rule within a Pack.
    59	type Rule struct {
    60		ID          string   `json:"id"                    yaml:"id"`
    61		Description string   `json:"description,omitempty" yaml:"description"`
    62		Regex       string   `json:"regex"                 yaml:"regex"`
    63		Samples     []Sample `json:"samples,omitempty"     yaml:"samples"`
    64	}
    65	
    66	// Sample is a self-test entry for a Rule. The runner asserts whether the
    67	// rule's regex matching `Input` matches the `Redacted` expectation.
    68	type Sample struct {
    69		Input    string `json:"input"    yaml:"input"`
    70		Redacted bool   `json:"redacted" yaml:"redacted"`
    71	}
    72	
    73	// ParsePack decodes a single pack file. sourcePath is used both to pick
    74	// the encoding (YAML by default; JSON only when the extension is .json)
    75	// and to enforce that the pack's `name` matches the filename stem.
    76	//
    77	// Precondition: sourcePath must be a vetted local file path (the production
    78	// caller is LoadPacks, which only invokes ParsePack with paths produced by
    79	// WalkDir under the configured .entire/redactors/ directory). Callers passing
    80	// arbitrary or remote paths must enforce their own trust model — ParsePack
    81	// does not sanitize sourcePath beyond reading its extension.
    82	func ParsePack(data []byte, sourcePath string) (*Pack, error) {
    83		var pack Pack
    84		switch strings.ToLower(filepath.Ext(sourcePath)) {
    85		case ".json":
    86			decoder := json.NewDecoder(bytes.NewReader(data))
    87			decoder.DisallowUnknownFields()
    88			if err := decoder.Decode(&pack); err != nil {
    89				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
    90			}
    91			var extra any
    92			if err := decoder.Decode(&extra); err == nil {
    93				return nil, fmt.Errorf("parse %s: trailing content after pack", sourcePath)
    94			} else if !errors.Is(err, io.EOF) {
    95				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
    96			}
    97		default:
    98			decoder := yaml.NewDecoder(bytes.NewReader(data))
    99			decoder.KnownFields(true)
   100			if err := decoder.Decode(&pack); err != nil {
   101				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
   102			}
   103			var extra any
   104			if err := decoder.Decode(&extra); err == nil {
   105				return nil, fmt.Errorf("parse %s: trailing content after pack", sourcePath)
   106			} else if !errors.Is(err, io.EOF) {
   107				return nil, fmt.Errorf("parse %s: %w", sourcePath, err)
   108			}
   109		}
   110		pack.sourcePath = sourcePath
   111		if err := validatePack(&pack); err != nil {
   112			return nil, err
   113		}
   114		return &pack, nil
   115	}
   116	
   117	// validatePack enforces required fields and schema invariants. Regex
   118	// compilation is NOT performed here — that happens during ConfigureCustomRules
   119	// so failures emit the same warn-and-skip path as inline rules.
   120	func validatePack(p *Pack) error {
   121		if p.Name == "" {
   122			return fmt.Errorf("%s: missing required field 'name'", p.sourcePath)
   123		}
   124		if err := validateIdentifier("name", p.Name, p.sourcePath); err != nil {
   125			return err
   126		}
   127		if p.Version == "" {
   128			return fmt.Errorf("%s: missing required field 'version'", p.sourcePath)
   129		}
   130		if len(p.Rules) == 0 {
   131			return fmt.Errorf("%s: 'rules' must contain at least one entry", p.sourcePath)
   132		}
   133	
   134		// Name must match filename stem so log lines and discovery stay consistent.
   135		stem := strings.TrimSuffix(filepath.Base(p.sourcePath), filepath.Ext(p.sourcePath))
   136		if stem != p.Name {
   137			return fmt.Errorf("%s: pack name %q does not match filename stem %q", p.sourcePath, p.Name, stem)
   138		}
   139	
   140		seen := make(map[string]struct{}, len(p.Rules))
   141		for i, r := range p.Rules {
   142			if r.ID == "" {
   143				return fmt.Errorf("%s: rules[%d] missing required field 'id'", p.sourcePath, i)
   144			}
   145			if err := validateIdentifier(fmt.Sprintf("rules[%d].id", i), r.ID, p.sourcePath); err != nil {
   146				return err
   147			}
   148			if r.Regex == "" {
   149				return fmt.Errorf("%s: rules[%d] (%s) missing required field 'regex'", p.sourcePath, i, r.ID)
   150			}
   151			if _, dup := seen[r.ID]; dup {
   152				return fmt.Errorf("%s: duplicate rule id %q", p.sourcePath, r.ID)
   153			}
   154			seen[r.ID] = struct{}{}
   155		}
   156		return nil
   157	}
   158	
   159	// validateIdentifier rejects pack Name / rule ID values that exceed the length
   160	// cap or contain characters outside identifierPattern. Both fields end up in
   161	// log attributes and (for Name) the filename comparison; bounding them keeps
   162	// diagnostics readable and prevents a malformed pack from polluting log lines.
   163	func validateIdentifier(field, value, sourcePath string) error {
   164		if len(value) > maxIdentifierLen {
   165			return fmt.Errorf("%s: %s %q exceeds %d-character limit", sourcePath, field, value, maxIdentifierLen)
   166		}
   167		if !identifierPattern.MatchString(value) {
   168			return fmt.Errorf("%s: %s %q contains characters outside [A-Za-z0-9._-]", sourcePath, field, value)
   169		}
   170		return nil
   171	}
   172	
   173	// LoadPacks discovers and parses all rule packs in dir, including any
   174	// subdirectories (so the conventional .entire/redactors/local/ path for
   175	// personal/uncommitted rules is picked up automatically). Files with the
   176	// extensions .yaml, .yml, and .json are considered packs; other files are
   177	// ignored. A missing directory is treated as "no packs configured" and
   178	// returns no error. Per-file parse errors are slog.Warn'd and the file is
   179	// skipped — never fatal — so one bad file does not silence the rest.
   180	//
   181	// Soft caps: files larger than maxPackFileBytes are skipped with a warning,
   182	// and discovery stops after maxPackFiles parsed packs. The trust boundary is
   183	// "user owns repo," so these are runaway-input guards, not security limits.
   184	func LoadPacks(dir string) ([]*Pack, error) {
   185		var packs []*Pack
   186		walkErr := filepath.WalkDir(dir, func(path string, d fs.DirEntry, err error) error {
   187			if err != nil {
   188				if path == dir {
   189					if os.IsNotExist(err) {
   190						return nil
   191					}
   192					return fmt.Errorf("read redactors dir %s: %w", dir, err)
   193				}
   194				slog.Warn("skipping unreadable redactor pack path",
   195					componentAttr,
   196					slog.String("path", path),
   197					slog.String("error", err.Error()))
   198				return nil
   199			}
   200			if path == dir && !d.IsDir() {
   201				return fmt.Errorf("redactors path %s is not a directory", dir)
   202			}
   203			if d.Type()&fs.ModeSymlink != 0 {
   204				slog.Warn("skipping symlinked redactor pack path",
   205					componentAttr,
   206					slog.String("path", path))
   207				return nil
   208			}
   209			if d.IsDir() {
   210				return nil
   211			}
   212			switch strings.ToLower(filepath.Ext(d.Name())) {
   213			case ".yaml", ".yml", ".json":
   214			default:
   215				return nil
   216			}
   217	
   218			if len(packs) >= maxPackFiles {
   219				slog.Warn("skipping redactor pack: file cap reached",
   220					componentAttr,
   221					slog.String("path", path),
   222					slog.Int("max_files", maxPackFiles))
   223				return filepath.SkipAll
   224			}
   225	
   226			info, statErr := d.Info()
   227			if statErr != nil {
   228				slog.Warn("skipping redactor pack: stat failed",
   229					componentAttr,
   230					slog.String("path", path),
   231					slog.String("error", statErr.Error()))
   232				return nil
   233			}
   234			if info.Size() > maxPackFileBytes {
   235				slog.Warn("skipping redactor pack: file exceeds size cap",
   236					componentAttr,
   237					slog.String("path", path),
   238					slog.Int64("size_bytes", info.Size()),
   239					slog.Int("max_bytes", maxPackFileBytes))
   240				return nil
   241			}
   242	
   243			data, err := os.ReadFile(path) //nolint:gosec // path comes from WalkDir under a configured dir
   244			if err != nil {
   245				slog.Warn("skipping unreadable redactor pack",
   246					componentAttr,
   247					slog.String("path", path),
   248					slog.String("error", err.Error()))
   249				return nil
   250			}
   251			pack, err := ParsePack(data, path)
   252			if err != nil {
   253				slog.Warn("skipping invalid redactor pack",
   254					componentAttr,
   255					slog.String("path", path),
   256					slog.String("error", err.Error()))
   257				return nil
   258			}
   259			packs = append(packs, pack)
   260			return nil
   261		})
   262		if walkErr != nil {
   263			return nil, fmt.Errorf("walk redactors dir %s: %w", dir, walkErr)
   264		}
   265		return packs, nil
   266	}
